  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  4→
  5→const corsHeaders = {
  6→  "Access-Control-Allow-Origin": "*",
  7→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  8→};
  9→
 10→/** Extract a usable email from various formats */
 11→function extractEmail(raw: string): string {
 12→  // Handle "Name <email@domain>" format
 13→  const match = raw.match(/<([^>]+)>/);
 14→  return (match ? match[1] : raw).trim().toLowerCase();
 15→}
 16→
 17→serve(async (req) => {
 18→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 19→
 20→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 21→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 22→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 23→
 24→  // Helper to log and respond
 25→  const logAndRespond = async (
 26→    status: number,
 27→    logData: { sender?: string | null; recipient?: string | null; user_id?: string | null; job_id?: string | null; status: string; error_message?: string | null; attachments_count?: number; resumes_created?: number },
 28→    responseBody: Record<string, unknown>
 29→  ) => {
 30→    try {
 31→      await supabase.from("email_ingest_logs").insert({
 32→        sender: logData.sender || null,
 33→        recipient: logData.recipient || null,
 34→        user_id: logData.user_id || null,
 35→        job_id: logData.job_id || null,
 36→        status: logData.status,
 37→        error_message: logData.error_message || null,
 38→        attachments_count: logData.attachments_count || 0,
 39→        resumes_created: logData.resumes_created || 0,
 40→      });
 41→    } catch (e) {
 42→      console.error("Failed to log email ingest:", e);
 43→      await logSystemError({
 44→        function_name: "email-ingest",
 45→        error_type: "INGEST_LOG_ERROR",
 46→        severity: "warning",
 47→        error_message: errorToMessage(e),
 48→        error_stack: errorToStack(e),
 49→        user_id: logData.user_id || null,
 50→        job_id: logData.job_id || null,
 51→      });
 52→    }
 53→    return new Response(JSON.stringify(responseBody), {
 54→      status,
 55→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 56→    });
 57→  };
 58→
 59→  try {
 60→    // Check global email ingestion toggle
 61→    const { data: config } = await supabase
 62→      .from("platform_config")
 63→      .select("email_ingestion_enabled")
 64→      .limit(1)
 65→      .single();
 66→
 67→    if (config && !config.email_ingestion_enabled) {
 68→      return await logAndRespond(403, { status: "rejected", error_message: "Email ingestion globally disabled" }, { error: "Email ingestion is globally disabled" });
 69→    }
 70→
 71→    // Parse incoming payload — support Postmark JSON, legacy JSON, and multipart/form-data
 72→    let sender: string | null = null;
 73→    let recipient: string | null = null;
 74→    const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
 75→
 76→    const contentType = req.headers.get("content-type") || "";
 77→
 78→    if (contentType.includes("application/json")) {
 79→      const body = await req.json();
 80→
 81→      // Postmark inbound webhook format
 82→      if (body.FromFull || body.ToFull || body.Attachments) {
 83→        // Postmark format
 84→        sender = body.FromFull?.Email || body.From ? extractEmail(body.From) : null;
 85→
 86→        // ToFull is an array in Postmark
 87→        if (body.ToFull && Array.isArray(body.ToFull) && body.ToFull.length > 0) {
 88→          recipient = body.ToFull[0].Email?.toLowerCase() || null;
 89→        } else if (body.To) {
 90→          recipient = extractEmail(body.To);
 91→        }
 92→
 93→        // Postmark attachments: array of { Name, Content (base64), ContentType, ContentLength }
 94→        if (body.Attachments && Array.isArray(body.Attachments)) {
 95→          for (const att of body.Attachments) {
 96→            if (!att.Name || !att.Content) continue;
 97→            // Only accept PDF and DOCX
 98→            const name = att.Name.toLowerCase();
 99→            if (!name.endsWith(".pdf") && !name.endsWith(".docx")) continue;
100→            const fileContent = Uint8Array.from(atob(att.Content), (c: string) => c.charCodeAt(0));
101→            attachmentFiles.push({ filename: att.Name, content: fileContent });
102→          }
103→        }
104→      } else {
105→        // Legacy JSON format (backward compatible)
106→        sender = body.sender || null;
107→        recipient = body.recipient || null;
108→
109→        if (body.attachments && Array.isArray(body.attachments)) {
110→          for (const att of body.attachments) {
111→            if (!att.filename || !att.content) continue;
112→            const fileContent = Uint8Array.from(atob(att.content), (c: string) => c.charCodeAt(0));
113→            attachmentFiles.push({ filename: att.filename, content: fileContent });
114→          }
115→        }
116→      }
117→    } else if (contentType.includes("multipart/form-data")) {
118→      // SendGrid/Mailgun multipart format (backward compatible)
119→      const formData = await req.formData();
120→
121→      const envelope = formData.get("envelope") as string | null;
122→      const fromField = formData.get("from") as string | null;
123→      const toField = formData.get("to") as string | null;
124→
125→      // Parse sender
126→      if (envelope) {
127→        try {
128→          const env = JSON.parse(envelope);
129→          if (env.from) sender = extractEmail(env.from);
130→        } catch { /* ignore */ }
131→      }
132→      if (!sender && fromField) sender = extractEmail(fromField);
133→
134→      // Parse recipient
135→      if (envelope) {
136→        try {
137→          const env = JSON.parse(envelope);
138→          if (env.to && Array.isArray(env.to) && env.to.length > 0) recipient = extractEmail(env.to[0]);
139→        } catch { /* ignore */ }
140→      }
141→      if (!recipient && toField) recipient = extractEmail(toField.split(",")[0]);
142→
143→      // Extract attachments
144→      const attachmentCount = parseInt(formData.get("attachments") as string || "0", 10);
145→      for (let i = 1; i <= Math.max(attachmentCount, 10); i++) {
146→        const file = formData.get(`attachment${i}`) as File | null;
147→        if (!file) continue;
148→        const buffer = await file.arrayBuffer();
149→        attachmentFiles.push({
150→          filename: file.name || `attachment_${i}`,
151→          content: new Uint8Array(buffer),
152→        });
153→      }
154→
155→      // Fallback: check for "attachment-info" pattern
156→      if (attachmentFiles.length === 0) {
157→        for (const [key, value] of formData.entries()) {
158→          if (key.startsWith("attachment") && value instanceof File) {
159→            const buffer = await value.arrayBuffer();
160→            attachmentFiles.push({
161→              filename: value.name || key,
162→              content: new Uint8Array(buffer),
163→            });
164→          }
165→        }
166→      }
167→    } else {
168→      return await logAndRespond(400, { status: "error", error_message: "Unsupported content type" }, { error: "Unsupported content type" });
169→    }
170→
171→    if (!recipient) {
172→      return await logAndRespond(400, { sender, recipient, status: "error", error_message: "No recipient" }, { error: "No recipient" });
173→    }
174→
175→    // Step 1: Try per-job routing — match recipient against jobs.inbox_email
176→    let jobId: string | null = null;
177→    let userId: string | null = null;
178→
179→    const { data: jobMatch } = await supabase
180→      .from("jobs")
181→      .select("id, user_id")
182→      .eq("inbox_email", recipient)
183→      .single();
184→
185→    if (jobMatch) {
186→      jobId = jobMatch.id;
187→      userId = jobMatch.user_id;
188→    }
189→
190→    // Step 2: Fall back to user-level inbox routing
191→    if (!userId) {
192→      // Strip +tag for matching: abc+xyz@domain → abc@domain
193→      const baseRecipient = recipient.replace(/\+[^@]*@/, "@");
194→
195→      const { data: profile } = await supabase
196→        .from("profiles")
197→        .select("user_id, credits, email_enabled, inbox_email")
198→        .or(`inbox_email.eq.${recipient},inbox_email.eq.${baseRecipient}`)
199→        .limit(1)
200→        .single();
201→
202→      if (!profile) {
203→        return await logAndRespond(404, { sender, recipient, status: "rejected", error_message: "Unknown inbox email" }, { error: "Unknown inbox email" });
204→      }
205→
206→      userId = profile.user_id;
207→
208→      // Check per-user email toggle
209→      if (!profile.email_enabled) {
210→        return await logAndRespond(403, { sender, recipient, user_id: userId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
211→      }
212→    } else {
213→      // Verify the job owner has email enabled
214→      const { data: profile } = await supabase
215→        .from("profiles")
216→        .select("email_enabled")
217→        .eq("user_id", userId)
218→        .single();
219→
220→      if (profile && !profile.email_enabled) {
221→        return await logAndRespond(403, { sender, recipient, user_id: userId, job_id: jobId, status: "rejected", error_message: "User email disabled" }, { error: "Email ingestion disabled for this user" });
222→      }
223→    }
224→
225→    if (attachmentFiles.length === 0) {
226→      return await logAndRespond(400, { sender, recipient, user_id: userId, job_id: jobId, status: "error", error_message: "No attachments" }, { error: "No attachments" });
227→    }
228→
229→    // Find or create job if not already matched by per-job routing
230→    if (!jobId) {
231→      const { data: activeJob } = await supabase
232→        .from("jobs")
233→        .select("id")
234→        .eq("user_id", userId)
235→        .eq("status", "pending")
236→        .order("created_at", { ascending: false })
237→        .limit(1)
238→        .single();
239→
240→      if (activeJob) {
241→        jobId = activeJob.id;
242→      } else {
243→        const { data: newJob } = await supabase
244→          .from("jobs")
245→          .insert({
246→            user_id: userId,
247→            job_description: "Auto-created from email ingestion",
248→            status: "pending",
249→          })
250→          .select("id")
251→          .single();
252→        if (!newJob) throw new Error("Failed to create job");
253→        jobId = newJob.id;
254→      }
255→    }
256→
257→    // Process attachments
258→    const resumeIds: string[] = [];
259→    for (const att of attachmentFiles) {
260→      const filePath = `${userId}/${jobId}/${Date.now()}_${att.filename}`;
261→      await supabase.storage.from("resumes").upload(filePath, att.content);
262→
263→      const { data: resume } = await supabase
264→        .from("resumes")
265→        .insert({
266→          job_id: jobId,
267→          filename: att.filename,
268→          file_path: filePath,
269→          source: "email",
270→        })
271→        .select("id")
272→        .single();
273→
274→      if (resume) resumeIds.push(resume.id);
275→    }
276→
277→    // Send confirmation email to the user (fire-and-forget)
278→    try {
279→      const { data: authUser } = await supabase.auth.admin.getUserById(userId!);
280→      const userEmail = authUser?.user?.email;
281→
282→      if (userEmail) {
283→        const { data: jobData } = await supabase.from("jobs").select("title, job_description").eq("id", jobId).single();
284→        const jobTitle = jobData?.title || jobData?.job_description?.slice(0, 50) || "Untitled Job";
285→
286→        await supabase.functions.invoke("send-email", {
287→          body: {
288→            to: userEmail,
289→            template_key: "resume_received",
290→            variables: {
291→              user_name: userEmail.split("@")[0],
292→              job_title: jobTitle,
293→              attachment_count: String(attachmentFiles.length),
294→              filename: attachmentFiles.map((a) => a.filename).join(", "),
295→              job_id: jobId || "",
296→              app_url: Deno.env.get("APP_URL") || "https://rankora.co",
297→            },
298→          },
299→        });
300→      }
301→    } catch (emailErr) {
302→      console.error("Failed to send resume received notification:", emailErr);
303→      await logSystemError({
304→        function_name: "email-ingest",
305→        error_type: "NOTIFICATION_SEND_ERROR",
306→        severity: "warning",
307→        error_message: errorToMessage(emailErr),
308→        error_stack: errorToStack(emailErr),
309→        user_id: userId,
310→        job_id: jobId,
311→      });
312→    }
313→
314→    return await logAndRespond(
315→      200,
316→      { sender, recipient, user_id: userId, job_id: jobId, status: "success", attachments_count: attachmentFiles.length, resumes_created: resumeIds.length },
317→      { success: true, resume_ids: resumeIds, job_id: jobId }
318→    );
319→  } catch (err: unknown) {
320→    console.error("email-ingest error:", err);
321→    await logSystemError({
322→      function_name: "email-ingest",
323→      error_type: "INGEST_ERROR",
324→      severity: "critical",
325→      error_message: errorToMessage(err),
326→      error_stack: errorToStack(err),
327→    });
328→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
329→      status: 500,
330→      headers: { ...corsHeaders, "Content-Type": "application/json" },
331→    });
332→  }
333→});
